const int TRIG = 9;
const int ECHO = 10;
float last = -1;
unsigned long lastAt = 0, nextAt = 0;

float ping() {
  digitalWrite(TRIG, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG, HIGH);   // a HIGH of at least 10 µs starts one ping
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  unsigned long us = pulseIn(ECHO, HIGH, 30000UL);   // give up after 30 ms (about 5 m): 0 means no echo
  if (us == 0) return -1;
  return us / 58.0;   // 58 µs of round trip per cm
}

void setup() {
  Serial.begin(9600);
  pinMode(TRIG, OUTPUT);
  pinMode(ECHO, INPUT);
  Serial.println("closing speed: a ping every 500 ms");
}

void loop() {
  unsigned long now = millis();
  if (now < nextAt) return;
  nextAt = now + 500;
  float cm = ping();
  if (cm < 0) Serial.print("no echo");
  else {
    Serial.print(cm, 1);
    Serial.print(" cm");
  }
  if (cm > 0 && last > 0) {
    float speed = (last - cm) / ((now - lastAt) / 1000.0);
    if (speed > 2) {
      Serial.print(", approaching at ");
      Serial.print(speed, 0);
      Serial.print(" cm/s");
    } else if (speed < -2) {
      Serial.print(", moving away at ");
      Serial.print(-speed, 0);
      Serial.print(" cm/s");
    } else {
      Serial.print(", holding");
    }
  }
  Serial.println();
  last = cm;
  lastAt = now;
}

